      "date": "2026-08-08"
    }
  ],
  "onlyYouClaim": [
    {
      "file": "features/marketing/search-console/intake/SiteIntakeWizard.tsx",
      "justification": "Not a privacy claim - intake copy meaning 'only you know the answer to these questions'.",
      "date": "2026-08-08"
    },
    {
      "file": "app/(dev)/demos/settings-primitives/page.dev.tsx",
      "justification": "Dev demo copy; harmless but wrong-vocabulary \u2014 sweep with D106b.",
      "date": "2026-08-08"
    },
    {
      "file": "app/(public)/free/zip-code-heatmap/components/SaveHeatmapModal.tsx",
      "justification": "Standalone public tool; its links are auth-gated per-user so the claim is close to true, but it uses the retired 'private' wording \u2014 sweep with D106b.",
      "date": "2026-08-08"
