files.scripts/access-guards/allowlist.json:
{
  "_comment": "Access guard allowlist. Every entry MUST carry a justification — this file is reviewed like code. Shape per detector below. Paths are repo-relative, forward-slash.",

  "_shape": {
    "lowestTierDefault": {
      "_comment": "Historical migrations predating the 2026-07-21 'personal' rename/policy are exempt by filename. New entries here require a dated justification, not just a filename.",
      "example": { "file": "migrations/20260101_old_default.sql", "justification": "Applied before 2026-07-21 visibility policy; grandfathered, do not edit.", "addedBy": "check-access-guards bootstrap", "date": "2026-07-22" }
    },
    "activeOrgAccess": {
      "_comment": "File-level or file:line-level suppressions for detector 2 (active-org reads inside access-decision files).",
      "example": { "file": "utils/permissions/someFile.ts", "line": 42, "justification": "Reads active org only for a UI label, not an access decision — grep context above/below confirms no .eq(...) gate follows.", "addedBy": "arman", "date": "2026-07-22" }
    },
    "handRolledLadder": {
      "_comment": "Files outside utils/permissions/** that legitimately compare permission_level strings (e.g. read-only display formatting, not an access decision).",
      "example": { "file": "features/sharing/components/RoleBadge.tsx", "justification": "Cosmetic label mapping only, never gates a read/write; the real check happens via iam.has_access upstream.", "addedBy": "arman", "date": "2026-07-22" }
    },
    "bareRlsList": {
      "_comment": "List-shaped Supabase reads in features/**/{service,services,redux}/** that are intentionally unscoped (e.g. genuinely public reference data, or scope handled by a wrapping RPC not visible in this chain).",
      "example": { "file": "features/ai-models/service.ts", "line": 10, "justification": "Public model catalog, world-readable by design, RLS enforces read-only; no owner/org scope applies.", "addedBy": "arman", "date": "2026-07-22" }
    }
  },

  "lowestTierDefault": [
    { "file": "migrations/working_document_shareable.sql", "justification": "Working documents are personal user-authored scratch documents by design; this migration makes the existing access-kernel fallback explicit without changing behavior. Users may deliberately share them afterward.", "addedBy": "codex (baseline merge)", "date": "2026-07-29" },
    { "file": "migrations/invitation_codes_private_credentials.sql", "justification": "Invitation codes are private credentials issued to individual recipients, never organization work or public catalog rows; the server validates exact candidates and anonymous callers cannot enumerate them.", "addedBy": "codex integration maintainer", "date": "2026-08-28" }
  ],
  "activeOrgAccess": [],
  "handRolledLadder": [
    { "file": "features/admin/relationships/components/RelationshipRulesClient.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/cx-chat/types/cx-tables.ts", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/marketing/components/access/SiteAccessWorkspace.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/marketing/data/access-service.ts", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/messaging/types.ts", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/notes/components/NoteSidebar.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/notes/components/mobile/MobileNotesList.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/notes/redux/notes.types.ts", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/organizations/components/OrgModuleSettings.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/public-chat/types/cx-tables.ts", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/sharing/components/PermissionsList.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/sharing/components/tabs/ShareWithOrgTab.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "features/sharing/components/tabs/ShareWithUserTab.tsx", "justification": "cosmetic UI union, no access decision", "addedBy": "claude", "date": "2026-07-22" },
    { "file": "lib/redux/slices/agentCacheSlice.ts", "line": 48, "justification": "cosmetic UI union, no access decision — display-only shared-cache metadata field", "addedBy": "claude", "date": "2026-07-22" }
  ],
  "bareRlsList": [
    { "file": "features/rag/hooks/useLibraryCatalog.ts", "justification": "D-E closure: the shared-knowledge catalog is DELIBERATELY a global discoverable list (rag.fn_list_library_catalog lists every discoverable+active store for every caller — that is what a catalog is for); per-caller state is carried in the entitled_via/subscribed columns, not by hiding rows. Scope is declared inside the SECURITY DEFINER RPC (auth.uid()-keyed entitlement mirror of user_can_read_data_store_via_grant), never by bare RLS.", "addedBy": "claude (P3 shared-knowledge)", "date": "2026-07-23" },
    { "file": "features/rag/hooks/useLibraryProvenance.ts", "justification": "D-E closure: provenance RPCs (public.library_grant_provenance/_batch) return ONLY grants reaching auth.uid() by definition; the rag.data_store_members read is filtered to explicit source_ids and RLS admits only own/org/grant-readable stores — decoration on content the caller already reads, not a browse list.", "addedBy": "claude (P3 shared-knowledge)", "date": "2026-07-23" },
    { "file": "features/rag/hooks/useDataStores.ts", "justification": "D-E closure: list rides rag.fn_list_user_data_stores / fn_get_user_data_store, SECURITY DEFINER functions that resolve identity from auth.uid() only and declare their own owner+org+grant scope — the ListScope primitive would duplicate the RPC's internal scoping.", "addedBy": "claude (P3 shared-knowledge)", "date": "2026-07-23" }
  ]
}

